//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDBNS30400.xml";
scwin.vs_G_BND_APPL_ID = ""; //종목상세조회화면팝업에 쓰임 
scwin.vs_G_BND_MKTACT_TP_CD = ""; //종목상세조회화면팝업에 쓰임 
scwin.vs_G_BND_MKTACT_TP_NM = ""; //종목상세조회화면팝업에 쓰임 
scwin.vs_G_BKBND_TP_CD = ""; //종목상세조회화면팝업에 쓰임 
scwin.vs_G_STRT_DD = ""; //종목상세조회화면팝업에 쓰임 
scwin.vs_G_STD_CD = ""; //종목상세조회화면팝업에 쓰임 

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vs_G_BND_APPL_ID,
        BND_MKTACT_TP_CD: scwin.vs_G_BND_MKTACT_TP_CD,
        BND_MKTACT_TP_NM: scwin.vs_G_BND_MKTACT_TP_NM,
        BKBND_TP_CD: scwin.vs_G_BKBND_TP_CD,
        STRT_DD: scwin.vs_G_STRT_DD,
        STD_CD: scwin.vs_G_STD_CD,
        ISUR_CD: vs_G_ISUR_CD
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 설명       : 종목선택목록 세팅
 ***********************************************/
scwin.fn_SetParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_ISUR_CD)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_COM_NM, arrPar[0].ISUR_NM);
    $c.stf.setObjectValue(txb_ISUR_CD, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(img_CoSearch) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_CoSearch);
};


/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISUR_NM: $c.stf.getObjectValue(txb_ISUR_CD),
        ISU_NM: $c.stf.getObjectValue(txb_ISU_CD)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_ISU_CD, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_ISU_NM, arrPar[0].ISU_NM);
};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();

    // 전체조회
    if (vsTabSel == "1") {
        scwin.fn_Search1();
        // 개별종목조회

    } else if (vsTabSel == "2") {
        scwin.fn_Search2();
        // 일괄상장종목조회

    } else if (vsTabSel == "3") {
        scwin.fn_Search3();
    }
};



/********************************************** 
 * 설명       : 전체조회
 ***********************************************/
scwin.fn_Search1 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CLS_PROCES_STAT_LIST";
    url += "&queryId=lds.stf.bnscls_proces_stat.select.list1";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + txb_ISUR_CD.getValue();
    url += "&{P}V_ISU_NM=" + txb_ISU_CD.getValue();
    url += "&{P}V_EMP_NM=" + txb_EmpNm.getValue();
    url += "&{P}V_MKT_RSN_CD=" + $c.stf.getObjectValue(cmb_MktStsGb);
    url += "&{P}V_STATE=" + $c.stf.getObjectValue(cmb_BndStsGb);
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EDate);
    url += "&{P}V_SRI_BND_TP_CD=" + $c.stf.getObjectValue(chk_SRI_BND_TP_CD);
    url += "&{P}V_DD_TP=" + $c.stf.getObjectValue(rdo_DD_TP);
    dts_List1.DataID = encodeURI(url);
    dts_List1.Reset();
    $c.cm.ShowWin(grd_List1);
};


/********************************************** 
 * 설명       : 개별종목조회
 ***********************************************/
scwin.fn_Search2 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CLS_PROCES_STAT_LIST";
    url += "&queryId=lds.stf.bnscls_proces_stat.select.list2";
