    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + txb_ISUR_CD.getValue();
    url += "&{P}V_ISU_NM=" + txb_ISU_CD.getValue();
    url += "&{P}V_EMP_NM=" + txb_EmpNm.getValue();
    url += "&{P}V_MKT_RSN_CD=" + $c.stf.getObjectValue(cmb_MktStsGb);
    url += "&{P}V_STATE=" + $c.stf.getObjectValue(cmb_BndStsGb);
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EDate);
    url += "&{P}V_DD_TP=" + $c.stf.getObjectValue(rdo_DD_TP);
    dts_List2.DataID = encodeURI(url);
    dts_List2.Reset();
    $c.cm.ShowWin(grd_List2);
};


/********************************************** 
 * 설명       : 일괄상장종목
 ***********************************************/
scwin.fn_Search3 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CLS_PROCES_STAT_LIST";
    url += "&queryId=lds.stf.bnscls_proces_stat.select.list3";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + txb_ISUR_CD.getValue();
    //url += "&{P}V_ISU_NM="           + txb_ISU_CD.value;
    url += "&{P}V_EMP_NM=" + txb_EmpNm.getValue();
    url += "&{P}V_MKT_RSN_CD=" + $c.stf.getObjectValue(cmb_MktStsGb);
    url += "&{P}V_STATE=" + $c.stf.getObjectValue(cmb_BndStsGb);
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_EDate);
    dts_List3.DataID = encodeURI(url);
    dts_List3.Reset();
    $c.cm.ShowWin(grd_List3);
};


/********************************************** 
 * 설명       : 일괄은행채권 월별등록현황
 ***********************************************/
scwin.fn_SearchDetail = function(row) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CLS_PROCES_STAT_LIST_DETAIL";
    url += "&queryId=lds.stf.bnscls_proces_stat.select.list3detail";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_APPL_ID=" + dts_List3.getCellData(row, 'BND_APPL_ID'); //

    dts_ListDet.DataID = encodeURI(url);
    dts_ListDet.Reset();
    $c.cm.ShowWin(grd_ListDetail);
};


/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGrid = null;
    var excelSheet = '';
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var xls_path = $c.session.getExcelDownPath();

    // 전체조회
    if (vsTabSel == "1") {
        xls_path = xls_path + "채권처리현황(전체)_" + today + ".xlsx";
        voDtsList = dts_List1;
        voGrid = grd_List1;
        // 개별종목조회

    } else if (vsTabSel == "2") {
        xls_path = xls_path + "채권처리현황(개별)_" + today + ".xlsx";
        voDtsList = dts_List2;
        voGrid = grd_List2;
        // 일괄상장종목조회

    } else if (vsTabSel == "3") {
        xls_path = xls_path + "채권처리현황(일괄)_" + today + ".xlsx";
        voDtsList = dts_List3;
        voGrid = grd_List3;
    }
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        voGrid.GridToOffice("sheet1", xls_path, 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};




/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown3 = function() {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var xls_path = $c.session.getExcelDownPath() + "채권처리현황(일괄월별)_" + today + ".xlsx";
    if (dts_ListDet.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_ListDetail, "sheet1", xls_path, 8, 0);
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);

    //시장조치
    var arrCid = [];
    arrCid.push({
        cid: '03057',
        cnm: 'cmb_MktStsGb'
    });
    $c.bns.fn_SetBnsComboToCode2(scwin.vScrenID, dts_Temp, arrCid, '전체');
    $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate); // 신청일 기간
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    scwin.fn_Search();
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_Search();
    }
};
scwin.img_CoSearch_onclick = function() {
    /********************************************** 
     * 함수명   : img_CoSearch > onclick
     * 설명      : 발행기관 조회
     ***********************************************/
    scwin.fn_ShowIsur(img_CoSearch);
};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    /********************************************** 
     * 함수명   : btn_ISU_CD_SEARCH > onclick
     * 설명      : 종목 조회
     ***********************************************/
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
};
scwin.txb_ISUR_CD_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISUR_CD > onblur
     * 설명      : 발행기관 코드 변경
     ***********************************************/
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISU_CD_onblur = function() {
    /********************************************** 
     * 함수명   : txb_ISU_CD > onblur
     * 설명      : 종목 코드 변경
     ***********************************************/
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.btn_SDate_onclick = function() {
    /********************************************** 
     * 함수명   : btn_SDate > onclick
     * 설명      : 신청일기간 시작일자 달력클릭
     ***********************************************/
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    /********************************************** 
