};
scwin.dts_List1_OnLoadError = function() {
    /********************************************** 
     * 함수명   : dts_List1 > OnLoadError
     * 설명      : dts_List1 조회 에러 
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * 함수명   : dts_List1 > OnLoadCompleted
     * 설명      : dts_List1 조회 성공
     ***********************************************/
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page1);
    $c.cm.CloseWin(rowcount, grd_List1);
    $c.cm.setColumnProp(grd_List1, 'PROC_STATE', 'color', "{decode(PROC_STATE,'처리중','#343434','처리완료','#343434','미처리','#FF0000','반송','#0000FF')}");
};
