scwin.chk_SRI_BND_TP_CD_onclick = function() {
    if ($c.stf.getObjectValue(chk_SRI_BND_TP_CD) == "Y" && tab_Main.getSelectedTabIndex() != 1) {
        $c.win.alert("[개별종목], [일괄상장종목] 탭은 ESG채권과 함께 사용 할 수 없습니다.");
        $c.stf.setObjectValue(chk_SRI_BND_TP_CD, "N");
    }
    if ($c.stf.getObjectValue(chk_SRI_BND_TP_CD) == "Y") {
        $c.stf.setObjectValue(rdo_DD_TP, "1");
        rdo_DD_TP.setDisabled(true);
    } else {
        rdo_DD_TP.setDisabled(false);
    }
};
